def set_left_most_unset_bit(num: int) -> int:
    """
    Set the leftmost unset bit in the binary representation of num.
    If all bits in the current representation are already set, set the
    next higher bit.
    """
    bit_len = num.bit_length()

    # Check from the most significant (leftmost) bit down to the least.
    for pos in range(bit_len - 1, -1, -1):
        if not (num & (1 << pos):
            return num | (1 << pos)

    # No zero bit found, so set the bit just above the current representation.
    return num | (1 << bit_len)


