def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)

    # The matrix must be square
    if any(len(row) != n for row in matrix):
        return False

    # Target sum from the first row
    target = sum(matrix[0])

    # Check all rows
    if any(sum(row) != target for row in matrix):
        return False

    # Check all columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True
