def minPath(grid, k):
    if k == 1:
        return [1]

    n = len(grid)
    sr = sc = -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                sr, sc = r, c
                break
        if sr != -1:
            break

    best = None
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1):
        nr, nc = sr + dr, sc + dc
        if 0 <= nr < n and 0 <= nc < n:
            val = grid[nr][nc]
            if best is None or val < best:
                best = val

    return [1 if step % 2 == 0 else best for step in range(k)]
