class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def all_substrings(x: str):
            res = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(x[i:j])
            return res

        ss = all_substrings(s)
        tt = all_substrings(t)

        ans = 0
        for left in ss:
            for right in tt:
                total = len(left) + len(right)
                if total <= ans:
                    continue
                cand = left + right
                if cand == cand[::-1]:
                    ans = total

