from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        # Segment tree storing the maximum available basket capacity in each segment.
        seg = [-1] * (2 * size)

        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def first_available(need: int) -> int:
            if seg[1] < need:
                return -1

            pos = 1
            while pos < size:
                left = pos * 2
                if seg[left] >= need:
                    pos = left
                else:
                    pos = left + 1

            return pos - size

        def remove_basket(idx: int) -> None:
            pos = size + idx
            seg[pos] = -1
            pos //= 2

            while pos:
                seg[pos] = max(seg[2 * pos], seg[2 * pos + 1])
                pos //= 2

        unplaced = 0

        for f in fruits:
            idx = first_available(f)

            if idx == -1:
                unplaced += 1
            else:
                remove_basket(idx)

        return unplaced
