        for idx, val in enumerate(elements):
            if val <= max_g and idx < first[val]:
                first[val] = idx

        # best[x] = smallest element index that divides x
        best = [INF] * (max_g + 1)

        for d in range(1, max_g + 1):
            idx = first[d]
            if idx == INF:
                continue
            for multiple in range(d, max_g + 1, d):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [best[g] if best[g] != INF else -1 for g in groups]
