    def parse_num(x):
        if not isinstance(x, str):
            return float(x)

        s = x.strip().replace(' ', '')
        if ',' in s and '.' in s:
            if s.rfind(',') > s.rfind('.'):
                s = s.replace('.', '').replace(',', '.')
            else:
                s = s.replace(',', '')
        elif ',' in s:
            if s.count(',') == 1:
                s = s.replace(',', '.')
            else:
                s = s.replace(',', '')
        return float(s)

    na = parse_num(a)
    nb = parse_num(b)

    if na == nb:
        return None
    return a if na > nb else b
