from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_extra = 0

        for target in range(1, 51):
            if target == k:
                continue

            cur = 0
            best_for_target = 0

            for v in nums:
                if v == target:
                    delta = 1
                elif v == k:
                    delta = -1
                else:
                    delta = 0

                cur = max(0, cur + delta)
                best_for_target = max(best_for_target, cur)

            best_extra = max(best_extra, best_for_target)

        return base + best_extra
